task.definition:
export interface Task {
  id: string;
  title: string;
  status: 'open' | 'done';
  dueDate: string | null;
  dueTime: string | null;
  list: string | null;
  priority: 1 | 2 | 3 | null;
  recurrence: Recurrence | null;
  createdAt: string;
  completedAt: string | null;
  order: number;
}

recurrence.definition:
export interface Recurrence {
  freq: 'daily' | 'weekly' | 'monthly';
  interval: number;
  byWeekday: number[] | null;
  byMonthDay: number | null;
}

app_data.definition:
export interface AppData {
  schemaVersion: 1;
  tasks: Task[];
}

chip.definition:
export interface Chip {
  start: number;
  end: number;
  kind: 'date' | 'time' | 'list' | 'priority' | 'recurrence';
  display: string;
}

parse_result.definition:
export interface ParseResult {
  valid: boolean;
  title: string;
  dueDate: string | null;
  dueTime: string | null;
  list: string | null;
  priority: 1 | 2 | 3 | null;
  recurrence: Recurrence | null;
  chips: Chip[];
  displaced: Range[];
}

range.definition:
export interface Range {
  start: number;
  end: number;
}

serialize_result.definition:
export interface SerializeResult {
  text: string;
  revertedRanges: Range[];
}

parsed_input_props.definition:
export interface ParsedInputProps {
  value: string;
  onChange: (value: string) => void;
  onSubmit: (result: ParseResult) => void;
  onCancel?: () => void;
  parseEnabled: boolean;
  initialReverts?: Range[];
  now?: Date;
  inputRef?: React.Ref<HTMLInputElement>;
  onKeyDown?: (e: React.KeyboardEvent<HTMLInputElement>) => boolean;
  inputProps?: React.InputHTMLAttributes<HTMLInputElement>;
  ariaLabel: string;
}
